;;; patch.s -- the launcher's game options, applied in RAM.
;;;
;;; A driver includes this, calls pt_apply after every load, and keeps an
;;; options byte, pt_opts, which the menu pokes before the game starts (the
;;; launcher page decides its value: asm/page.s).  PT_TAB is the game's
;;; patch table, generated by patches.py:
;;;
;;;   per patch: mask, address (2), n, the n original bytes, the n new ones
;;;   a zero mask ends it
;;;
;;; A patch is applied when its option is on and every original byte is
;;; there -- so it only ever lands in the code it was made for, whichever
;;; unit happens to be loaded at that address, and a second call finds it
;;; already applied and leaves it.  The build checks each patch's original
;;; bytes against every unit the game can load over them (patches.check).
;;;
;;; No zero page: self-modified absolute operands, as in tclib.
;;;
;;; PT_STREAM: the table is not in RAM but in the cart, pt_where its
;;; address (3) and length (2) -- filled in by the host's build -- and it is
;;; read through tclib's stream after the load, one entry at a time, each
;;; applied as it passes: the same format, the same rule, and no room taken
;;; by the table (Ultima 5, whose driver has none left).  Only when an option
;;; is on.  The host keeps pt_opts, pa_on, pa_n and pt_where.

!ifdef PT_LONG {
;;; PT_LONG: a table longer than 256 bytes (Ultima 4's).  The same walk, the
;;; table read through a self-modified 16-bit pointer, advanced patch by
;;; patch, instead of X.  The host keeps pt_opts, pa_on, pa_n.
pt_apply:
        lda #<PT_TAB
        sta pa_tb+1
        lda #>PT_TAB
        sta pa_tb+2
pa_next:
        ldy #$00
        jsr pa_tb               ; the mask; zero ends the table
        beq pa_out
        and pt_opts
        sta pa_on
        iny
        jsr pa_tb
        sta pa_rd+1
        sta pa_wr+1
        iny
        jsr pa_tb
        sta pa_rd+2
        sta pa_wr+2
        iny
        jsr pa_tb
        sta pa_n
        ldx #$00                ; x: the byte in memory, y: in the table
-       cpx pa_n                ; are the original bytes there?
        beq pa_hit
        iny
        jsr pa_tb
pa_rd:  cmp $ffff,x
        bne pa_skip
        inx
        bne -
pa_hit: lda pa_on
        beq pa_skip
        ldx #$00
-       txa                     ; the new bytes: 4 + n + x into the patch
        clc
        adc pa_n
        adc #$04
        tay
        jsr pa_tb
pa_wr:  sta $ffff,x
        inx
        cpx pa_n
        bne -
pa_skip:
        lda pa_n                ; the next patch: 4 + 2n on
        asl
        clc
        adc #$04
        adc pa_tb+1
        sta pa_tb+1
        bcc pa_next
        inc pa_tb+2
        bne pa_next             ; always
pa_out: rts
pa_tb:  lda $ffff,y             ; the table, y bytes into this patch
        rts
} else {
!ifdef PT_STREAM {
pt_apply:
        lda pt_opts
        beq pa_out              ; no option on: nothing to read
        ldx #4
-       lda pt_where,x          ; tc_addr (3), then tc_len (2)
        sta tc_addr,x
        dex
        bpl -
        jsr tc_stream_open
pa_next:
        jsr pa_get              ; the mask; zero ends the table
        beq pa_end
        and pt_opts
        sta pa_on
        jsr pa_get
        sta pa_rd+1
        sta pa_wr+1
        jsr pa_get
        sta pa_rd+2
        sta pa_wr+2
        jsr pa_get
        sta pa_n
        ldy #$00
-       jsr pa_get              ; the original bytes: one differs, and it is off
pa_rd:  cmp $ffff,y
        beq +
        lda #$00
        sta pa_on
+       iny
        cpy pa_n
        bne -
        ldy #$00
-       jsr pa_get              ; the new ones
        ldx pa_on
        beq +
pa_wr:  sta $ffff,y
+       iny
        cpy pa_n
        bne -
        beq pa_next             ; always
pa_end: jsr tc_stream_close
pa_out: rts
pa_get: jsr tc_stream_byte      ; (it keeps the caller's flags: Z from A here)
        cmp #$00
        rts
} else {
pt_apply:
        ldx #$00
pa_next:
        lda PT_TAB,x            ; the mask; zero ends the table
        beq pa_out
        and pt_opts
        sta pa_on
        lda PT_TAB+1,x
        sta pa_rd+1
        sta pa_wr+1
        lda PT_TAB+2,x
        sta pa_rd+2
        sta pa_wr+2
        lda PT_TAB+3,x
        sta pa_n
        inx
        inx
        inx
        inx
        stx pa_x
        ldy #$00
-       cpy pa_n                ; are the original bytes there?
        beq pa_hit
pa_rd:  lda $ffff,y
        cmp PT_TAB,x
        bne pa_skip
        inx
        iny
        bne -
pa_hit: lda pa_on
        beq pa_skip
        ldy #$00                ; x: the new bytes
-       lda PT_TAB,x
pa_wr:  sta $ffff,y
        inx
        iny
        cpy pa_n
        bne -
pa_skip:
        lda pa_n                ; the next patch: 2n on
        asl
        adc pa_x
        tax
        jmp pa_next
pa_out: rts
}
}
